class Solution {
public:
    int maxSumDivThree(vector<int>& nums) {
        const long long NEG = LLONG_MIN;
        vector<long long> dp(3, NEG);
        dp[0] = 0;
        for (int x : nums) {
            vector<long long> ndp = dp;
            for (int r = 0; r < 3; r++) {
                if (dp[r] != NEG) {
                    int nr = (r + x) % 3;
                    ndp[nr] = max(ndp[nr], dp[r] + x);
                }
            }
            dp = ndp;
        }
        return (int)dp[0];
    }
};
